import{_ as r,l as n,o as e,c as l,v as t,p as s,x as o,d,i as E,S as p}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"机密计算","description":"","frontmatter":{"title":"机密计算","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/confidential-computing.md","filePath":"cs/confidential-computing.md","lastUpdated":1789023840000}'),c={name:"cs/confidential-computing.md"};function h(u,a,m,T,_,f){const i=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="机密计算" tabindex="-1">机密计算 <a class="header-anchor" href="#机密计算" aria-label="Permalink to &quot;机密计算&quot;">​</a></h1><div class="epigraph"><p>机密计算承诺：云运营商看不见客户明文内存。实现靠 TEE、内存加密与证明。合同要写清谁是 TCB：CPU 厂商、主机固件、飞地代码。</p><footer>—— 据 Confidential Computing Consortium 的定义陈述；对照 Costan–Devadas；NIST 对 TEE 的讨论</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/tee-sgx-trustzone">TEE</a>给硬件盒子。缺口是<strong>云威胁模型</strong>：hypervisor 好奇。本课把产品叙事钉成 TCB 清单，不写打穿虚拟机的步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>磁盘加密挡不了运行中内存。机密虚拟机把客户内存对宿主管员加密。缺口是证明与密钥释放策略：证明失败则不交密钥。</p><h3 id="不是零泄露" tabindex="-1">不是零泄露 <a class="header-anchor" href="#不是零泄露" aria-label="Permalink to &quot;不是零泄露&quot;">​</a></h3><p>侧信道、嵌套、设备直通可漏。合同不是营销词。</p><p><span class="marginnote">CCC。远程证明下一课专收度量与报价。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>列 TCB：CPU、固件、VMM 最小化、客户飞地。对照 HSM。下一课远程证明。</p>',12)),(e(),s(p,null,{default:o(()=>[E(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20TENANT%5B%22%E7%A7%9F%E6%88%B7%E6%98%8E%E6%96%87%22%5D%20--%3E%20TEE%5B%22%E5%86%85%E5%AD%98%E5%8A%A0%E5%AF%86%E9%A3%9E%E5%9C%B0%22%5D%0A%20%20HOST%5B%22%E8%BF%90%E8%90%A5%E5%95%86%22%5D%20-.-%3E%7C%22%E9%BB%98%E8%AE%A4%E4%B8%8D%E5%8F%AF%E8%AF%BB%22%7C%20TEE%0A%20%20ATTEST%5B%22%E8%AF%81%E6%98%8E%22%5D%20--%3E%20KEY%5B%22%E6%89%8D%E9%87%8A%E6%94%BE%E5%AF%86%E9%92%A5%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>云上的 C 对运营商。证明把「我是真飞地」变成可验声明。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写逃逸。远程证明下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>TEE 零件；机密计算是云威胁模型。</li><li>TCB 必须写进合同。</li><li>密钥释放绑证明。</li><li>下一课远程证明。</li><li>出处：Confidential Computing Consortium；Costan and Devadas。</li></ul>',8))])}const B=r(c,[["render",h]]);export{A as __pageData,B as default};
